const uniqueUrls = new Set();
const output = [];

for (const item of $input.all()) {
  const text =
    item.json?.content?.find(c => c?.type === 'text')?.text ||
    item.json?.text ||
    '';

  if (!text) {
    continue;
  }

  // Récupérer le JSON contenu dans ```json ... ```
  const match = text.match(/```json\s*([\s\S]*?)\s*```/i);

  if (!match) {
    continue;
  }

  let images;

  try {
    images = JSON.parse(match[1]);
  } catch (error) {
    continue;
  }

  if (!Array.isArray(images)) {
    continue;
  }

  for (const image of images) {
    const url = image?.src || '';

    if (
      url.startsWith('https://flow.google.com/asb/') &&
      !uniqueUrls.has(url)
    ) {
      uniqueUrls.add(url);

      output.push({
        json: {
          url: url,
          type: image.type || 'img',
          imageIndex: image.index ?? null,
          alt: image.alt || '',
          width: image.width ?? null,
          height: image.height ?? null
        }
      });
    }
  }
}

return output;

const output = [];

for (const item of $input.all()) {
  const text =
    item.json?.content?.find(c => c?.type === 'text')?.text ||
    item.json?.text ||
    '';

  const match = text.match(
    /data:(image\/[a-zA-Z0-9.+-]+);base64,([A-Za-z0-9+/=\r\n]+)/
  );

  if (!match) {
    continue;
  }

  const mimeType = match[1];
  const base64 = match[2].replace(/\s/g, '');

  const extension =
    mimeType === 'image/webp' ? 'webp' :
    mimeType === 'image/png' ? 'png' :
    mimeType === 'image/jpeg' ? 'jpg' :
    'bin';

  const buffer = Buffer.from(base64, 'base64');

  const binaryData = await this.helpers.prepareBinaryData(
    buffer,
    `flow-image-${item.index ?? 0}.${extension}`,
    mimeType
  );

  output.push({
    json: {
      mimeType,
      base64Length: base64.length
    },
    binary: {
      data: binaryData
    }
  });
}

return output;

const narrationsSource = $('Liste des 20 prompts').first().json.narrations;

return $input.all().map((item, index) => {
  return {
    json: {
      ...item.json,
      narration:
        narrationsSource[index] ||
        narrationsSource[narrationsSource.length - 1]
    },
    binary: item.binary
  };
});

const items = $input.all();

return items.map((item, index) => ({
  json: {
    scene: index + 1,
    image_url: item.json.secure_url
  }
}));

const scenes = $input.all()
  .map(item => item.json)
  .sort((a, b) => Number(a.scene) - Number(b.scene));

if (scenes.length === 0) {
  throw new Error("Aucune scène reçue.");
}

for (const scene of scenes) {
  if (
    !scene.image_url ||
    !scene.audio_url ||
    !Number.isFinite(Number(scene.duration)) ||
    Number(scene.duration) <= 0
  ) {
    throw new Error(
      `Données manquantes ou invalides pour la scène ${scene.scene}`
    );
  }
}

// Échapper les valeurs pour le shell
function quote(value) {
  return "'" + String(value).replace(/'/g, "'\\''") + "'";
}

const dir = "/tmp/n8n-video";

const commands = [
  "set -e",
  `mkdir -p ${dir}`,
  `rm -f ${dir}/scene_*.mp4 ${dir}/image_*.webp ${dir}/audio_*.mp3 ${dir}/concat.txt ${dir}/final_video.mp4`
];

for (const scene of scenes) {
  const n = Number(scene.scene);

  const image = `${dir}/image_${n}.webp`;
  const audio = `${dir}/audio_${n}.mp3`;
  const video = `${dir}/scene_${n}.mp4`;

  // Télécharger l'image depuis Cloudinary avec wget
  commands.push(
    `wget -q ${quote(scene.image_url)} -O ${quote(image)}`
  );

  // Télécharger l'audio depuis Cloudinary avec wget
  commands.push(
    `wget -q ${quote(scene.audio_url)} -O ${quote(audio)}`
  );

  // Générer la vidéo de la scène avec son audio
  commands.push(
    `ffmpeg -y -loop 1 -framerate 30 -i ${quote(image)} ` +
    `-i ${quote(audio)} ` +
    `-map 0:v:0 -map 1:a:0 ` +
    `-vf "scale=1080:1920:force_original_aspect_ratio=decrease,` +
    `pad=1080:1920:(ow-iw)/2:(oh-ih)/2,setsar=1,fps=30" ` +
    `-t ${Number(scene.duration)} ` +
    `-c:v libx264 -preset veryfast -pix_fmt yuv420p ` +
    `-c:a aac -b:a 192k -ar 48000 ` +
    `-shortest -movflags +faststart ${quote(video)}`
  );
}

// Préparer la liste des vidéos dans l'ordre des scènes
const concatContent = scenes
  .map(scene => `file '${dir}/scene_${Number(scene.scene)}.mp4'`)
  .join("\n");

// Créer le fichier de concaténation
commands.push(
  `printf '%s\\n' ${quote(concatContent)} > ${quote(`${dir}/concat.txt`)}`
);

// Fusionner les 5 scènes en une seule vidéo MP4
commands.push(
  `ffmpeg -y -f concat -safe 0 -i ${quote(`${dir}/concat.txt`)} ` +
  `-c copy -movflags +faststart ${quote(`${dir}/final_video.mp4`)}`
);

// Vérifier la durée et la taille de la vidéo finale
commands.push(
  `ffprobe -v error -show_entries format=duration,size ` +
  `-of default=noprint_wrappers=1 ${quote(`${dir}/final_video.mp4`)}`
);

// Retourner la commande au nœud Execute Command
return [
  {
    json: {
      command: commands.join(" && "),
      output_path: `${dir}/final_video.mp4`,
      scenes_count: scenes.length
    }
  }
];

const items = $input.all();

return items
  .map((item, index) => {
    const d = item.json;

    const imageUrl = d.image_url;

    // Ton audio Cloudinary est dans secure_url
    const audioUrl = d.secure_url;

    const duration = Number(d.duration);

    if (!imageUrl || !audioUrl || !duration) {
      return null;
    }

    return {
      json: {
        scene: Number(d.scene ?? index + 1),
        image_url: imageUrl,
        audio_url: audioUrl,
        duration
      }
    };
  })
  .filter(Boolean)
  .sort((a, b) => a.json.scene - b.json.scene);
